import { chromium } from "playwright";

// server/assets.ts
import fs from "node:fs";
import path from "node:path";
var MIME = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  gif: "image/gif",
  svg: "image/svg+xml"
};
function toDataUri(src) {
  if (src.startsWith("data:") || src.startsWith("http://") || src.startsWith("https://")) return src;
  const abs = path.resolve(src);
  const ext = path.extname(abs).slice(1).toLowerCase();
  const buf = fs.readFileSync(abs);
  return `data:${MIME[ext] ?? "application/octet-stream"};base64,${buf.toString("base64")}`;
}

// server/static-server.ts
import http from "node:http";
import fs2 from "node:fs";
import path2 from "node:path";
var MIME2 = {
  ".html": "text/html",
  ".js": "text/javascript",
  ".mjs": "text/javascript",
  ".css": "text/css",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".woff2": "font/woff2",
  ".woff": "font/woff"
};
function serveDir(dir) {
  const rootAbs = path2.resolve(dir);
  return new Promise((resolve) => {
    const server2 = http.createServer((req, res) => {
      try {
        const urlPath = decodeURIComponent((req.url || "/").split("?")[0]);
        const rel = urlPath === "/" ? "/index.html" : urlPath;
        const filePath = path2.join(rootAbs, rel);
        if (!filePath.startsWith(rootAbs)) {
          res.writeHead(403);
          res.end();
          return;
        }
        const data = fs2.readFileSync(filePath);
        res.writeHead(200, { "content-type": MIME2[path2.extname(filePath)] ?? "application/octet-stream" });
        res.end(data);
      } catch {
        res.writeHead(404);
        res.end();
      }
    });
    server2.listen(0, "127.0.0.1", () => {
      const addr = server2.address();
      resolve({
        origin: `http://127.0.0.1:${addr.port}`,
        close: () => new Promise((r) => server2.close(() => r()))
      });
    });
  });
}

// server/render.ts
function resolveAssets(spec) {
  return {
    ...spec,
    background: spec.background.image ? { ...spec.background, image: toDataUri(spec.background.image) } : spec.background,
    slots: spec.slots.map(
      (s) => s.screenshot ? { ...s, screenshot: toDataUri(s.screenshot) } : s
    )
  };
}
async function composeToPng(spec, opts) {
  const resolved = resolveAssets(spec);
  const { origin, close } = await serveDir(opts.distDir);
  const browser = await chromium.launch();
  try {
    const context = await browser.newContext({
      viewport: {
        width: Math.min(spec.canvas.width, 4096),
        height: Math.min(spec.canvas.height, 4096)
      },
      deviceScaleFactor: spec.exportScale
    });
    const page = await context.newPage();
    await page.goto(`${origin}/render.html`);
    await page.waitForFunction(() => typeof window.renderSpec === "function");
    await page.evaluate((s) => window.renderSpec(s), resolved);
    const stage = page.locator("[data-stage]");
    await stage.waitFor({ state: "visible" });
    const png = await stage.screenshot({ type: "png" });
    return png;
  } finally {
    await browser.close();
    await close();
  }
}

